type BackoffConfig struct {
	// BaseDelay is the amount of time to wait before retrying after the first failure.
	BaseDelay time.Duration
	// Multiplier is applied to the backoff after each retry.
	Multiplier float64
	// Jitter provides a range to randomize backoff delays.
	Jitter float64
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
}

var DefaultBackoffConfig = BackoffConfig{
	BaseDelay: 1 * time.Second,
	Multiplier: 1.6,
	Jitter: 0.2,
	MaxDelay: 120 * time.Second,
}

func WithBackoffConfig(b BackoffConfig) DialOption {
	if b.BaseDelay == 0 {
		b.BaseDelay = DefaultBackoffConfig.BaseDelay
	}
	if b.Multiplier == 0 {
		b.Multiplier = DefaultBackoffConfig.Multiplier
	}
	if b.Jitter == 0 {
		b.Jitter = DefaultBackoffConfig.Jitter
	}
	return withBackoff(backoff.Exponential{
		BaseDelay: b.BaseDelay,
		Multiplier: b.Multiplier,
		Jitter: b.Jitter,
		MaxDelay: b.MaxDelay,
	})
}

type Exponential struct {
	// BaseDelay is the amount of time to wait before retrying after the first failure.
	BaseDelay time.Duration
	// Multiplier is applied to the backoff after each retry.
	Multiplier float64
	// Jitter provides a range to randomize backoff delays.
	Jitter float64
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
}

func (bc Exponential) Backoff(retries int) time.Duration {
	base, multiplier, jitterFactor := bc.BaseDelay, bc.Multiplier, bc.Jitter
	if base == 0 {
		base = baseDelay
	}
	if multiplier == 0 {
		multiplier = factor
	}
	if jitterFactor == 0 {
		jitterFactor = jitter
	}
	if retries == 0 {
		return base
	}
	backoff, max := float64(base), float64(bc.MaxDelay)
	for backoff < max && retries > 0 {
		backoff *= multiplier
		retries--
	}
	if backoff > max {
		backoff = max
	}
	// Randomize backoff delays so that if a cluster of requests start at
	// the same time, they won't operate in lockstep.
	backoff *= 1 + jitterFactor*(grpcrand.Float64()*2-1)
	if backoff < 0 {
		return 0
	}
	return time.Duration(backoff)
}

